# Coordinates Jira work delivery into this repository's GitHub Actions workflows.
# Required to enforce delivery-policy gates, maintain the Jira lease, dispatch
# triage or code work, and reconcile execution evidence without exposing secrets.
"""Repository-local GitHub Actions Jira delivery controller.

Executes the common 6-stage lifecycle:
  1. Validate (Route cardinality, stage gate, project/work-type, optional sprint)
  2. Claim (Authoritative Jira entity-property lease)
  3. Re-read / Revalidate (Verify lease ownership without race conditions)
  4. Dispatch (Repository-local workflow dispatch or step execution)
  5. Evidence (Collect execution logs and outputs with secret redaction)
  6. Reconcile (Update Jira labels/status, release lease, post projection comment)
"""

import argparse
import base64
from datetime import datetime, timezone
import json
import os
import re
import subprocess
import sys
import urllib.error
import urllib.parse
import urllib.request
import uuid


CLAIM_PROPERTY_KEY = "uie.fullsend.claim"
TRIAGE_PROPERTY_KEY = "uie.fullsend.triage"
DEFAULT_LEASE_TTL_MINUTES = 60
DEFAULT_JIRA_URL = "https://redhat.atlassian.net"


def redact_secrets(text: str, extra_patterns: list[str] | None = None) -> str:
    """Redact sensitive credentials, tokens, and authorization headers from text."""
    if not text:
        return ""

    patterns = [
        r"ghp_[A-Za-z0-9]{36,}",
        r"gho_[A-Za-z0-9]{36,}",
        r"ghu_[A-Za-z0-9]{36,}",
        r"ghs_[A-Za-z0-9]{36,}",
        r"ghr_[A-Za-z0-9]{36,}",
        r"github_pat_[A-Za-z0-9_]{40,}",
        r"Bearer\s+[A-Za-z0-9._~+/=-]+",
        r"Basic\s+[A-Za-z0-9+/=]+",
        r"sk-[A-Za-z0-9_-]{16,}",
        r"pk-[A-Za-z0-9_-]{16,}",
        r"sk-lf-[A-Za-z0-9_-]{16,}",
        r"pk-lf-[A-Za-z0-9_-]{16,}",
    ]

    redacted = text
    for pat in patterns:
        redacted = re.sub(pat, "[REDACTED]", redacted)

    # Redact known environment variables
    for env_key in ("GITHUB_TOKEN", "GH_TOKEN", "FULLSEND_JIRA_API_TOKEN", "JIRA_API_TOKEN"):
        val = os.environ.get(env_key)
        if val and len(val) >= 4:
            redacted = redacted.replace(val, "[REDACTED]")

    if extra_patterns:
        for extra in extra_patterns:
            if extra and len(extra) >= 4:
                redacted = redacted.replace(extra, "[REDACTED]")

    return redacted


class SimpleJiraClient:
    """Lightweight Jira client using standard library only."""

    def __init__(self, base_url: str, email: str, token: str):
        if not base_url.lower().startswith("https://"):
            raise ValueError(
                f"Jira base URL must use HTTPS scheme for secure credential transport: '{base_url}'"
            )
        self.base_url = base_url.rstrip("/")
        self.auth_header = (
            "Basic " + base64.b64encode(f"{email}:{token}".encode("utf-8")).decode("ascii")
            if email and token
            else None
        )

    def _request(
        self, method: str, path: str, data: dict | list | None = None, allow_404: bool = False
    ) -> tuple[int, dict | list | None]:
        url = f"{self.base_url}{path}"
        headers = {"Accept": "application/json"}
        if self.auth_header:
            headers["Authorization"] = self.auth_header

        body_bytes = None
        if data is not None:
            body_bytes = json.dumps(data).encode("utf-8")
            headers["Content-Type"] = "application/json"

        req = urllib.request.Request(url, data=body_bytes, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                status = resp.status
                raw = resp.read()
                parsed = json.loads(raw.decode("utf-8")) if raw else None
                return status, parsed
        except urllib.error.HTTPError as err:
            if err.code == 404 and allow_404:
                return 404, None
            error_body = ""
            try:
                error_body = err.read().decode("utf-8")
            except Exception:
                pass
            raise RuntimeError(f"Jira API error {err.code} on {method} {path}: {error_body}") from err

    def get_issue(self, ticket_id: str) -> dict:
        ticket_key = validate_ticket_key(ticket_id)
        status, data = self._request("GET", f"/rest/api/3/issue/{ticket_key}")
        if status != 200 or not isinstance(data, dict):
            raise RuntimeError(f"Could not fetch Jira issue {ticket_id}")
        return data

    def get_issue_property(self, ticket_id: str, key: str) -> dict | None:
        ticket_key = validate_ticket_key(ticket_id)
        encoded_key = urllib.parse.quote(key, safe="")
        status, data = self._request("GET", f"/rest/api/3/issue/{ticket_key}/properties/{encoded_key}", allow_404=True)
        if status == 200 and isinstance(data, dict):
            return data.get("value")
        return None

    def set_issue_property(self, ticket_id: str, key: str, value: dict) -> None:
        ticket_key = validate_ticket_key(ticket_id)
        encoded_key = urllib.parse.quote(key, safe="")
        self._request("PUT", f"/rest/api/3/issue/{ticket_key}/properties/{encoded_key}", data=value)

    def delete_issue_property(self, ticket_id: str, key: str) -> None:
        ticket_key = validate_ticket_key(ticket_id)
        encoded_key = urllib.parse.quote(key, safe="")
        self._request("DELETE", f"/rest/api/3/issue/{ticket_key}/properties/{encoded_key}", allow_404=True)

    def add_label(self, ticket_id: str, label: str) -> None:
        ticket_key = validate_ticket_key(ticket_id)
        body = {"update": {"labels": [{"add": label}]}}
        self._request("PUT", f"/rest/api/3/issue/{ticket_key}", data=body)

    def remove_label(self, ticket_id: str, label: str) -> None:
        ticket_key = validate_ticket_key(ticket_id)
        body = {"update": {"labels": [{"remove": label}]}}
        try:
            self._request("PUT", f"/rest/api/3/issue/{ticket_key}", data=body)
        except Exception:
            pass

    def add_comment(self, ticket_id: str, comment_text: str) -> None:
        ticket_key = validate_ticket_key(ticket_id)
        clean_text = redact_secrets(comment_text)
        lines = clean_text.splitlines()
        content = []
        for line in lines:
            if line:
                content.append({"type": "paragraph", "content": [{"type": "text", "text": line}]})
            else:
                content.append({"type": "paragraph", "content": []})
        if not content:
            content.append({"type": "paragraph", "content": []})

        body = {"body": {"type": "doc", "version": 1, "content": content}}
        self._request("POST", f"/rest/api/3/issue/{ticket_key}/comment", data=body)


JIRA_TICKET_KEY_REGEX = re.compile(r"^[A-Z][A-Z0-9]+-[0-9]+$")


def validate_ticket_key(ticket_id: str) -> str:
    """Validate ticket_id strictly matches Jira issue key format and return URL-quoted key."""
    if not isinstance(ticket_id, str) or not JIRA_TICKET_KEY_REGEX.match(ticket_id.strip()):
        raise ValueError(
            f"Invalid Jira issue key format: '{ticket_id}'. Expected canonical format like 'FRFLY-123'."
        )
    return urllib.parse.quote(ticket_id.strip(), safe="")


def validate_route_cardinality(labels: list[str], expected_repo: str) -> str:
    """Verify route cardinality: exactly one matching repo route label."""
    expected_route = f"repo:github/{expected_repo.lower()}"
    route_labels = [lbl for lbl in labels if lbl.startswith("repo:")]

    if not route_labels:
        raise ValueError(
            f"Route cardinality violation: No repo route label found. Expected: {expected_route}"
        )

    if len(route_labels) > 1:
        raise ValueError(
            f"Route cardinality violation: Multiple repo route labels found: {route_labels}. "
            f"Cardinality must be exactly 1."
        )

    found_route = route_labels[0].lower()
    if found_route != expected_route:
        raise ValueError(
            f"Route mismatch: Ticket is routed to '{found_route}', but this controller is running "
            f"for '{expected_route}'."
        )

    return route_labels[0]


try:
    import yaml
except ImportError:
    yaml = None


def _parse_yaml_fallback(text: str) -> dict:
    """Line-based nested dict parser for 2-space indented YAML fallback."""
    root: dict = {}
    stack: list[tuple[int, dict]] = [(-1, root)]

    for raw_line in text.splitlines():
        line_no_comment = raw_line.split("#", 1)[0].rstrip()
        if not line_no_comment or not line_no_comment.strip():
            continue

        indent = len(line_no_comment) - len(line_no_comment.lstrip())
        content = line_no_comment.strip()
        if ":" not in content:
            continue

        k, v = content.split(":", 1)
        k = k.strip().strip('"').strip("'")
        v = v.strip()

        while stack and stack[-1][0] >= indent:
            stack.pop()

        parent = stack[-1][1] if stack else root

        if v == "":
            new_dict: dict = {}
            parent[k] = new_dict
            stack.append((indent, new_dict))
        else:
            val: Any = v.strip('"').strip("'")
            if val.lower() == "true":
                val = True
            elif val.lower() == "false":
                val = False
            elif val.isdigit():
                val = int(val)
            parent[k] = val

    return root


def load_delivery_policy(policy_path: str = ".fullsend/delivery-policy.yaml") -> dict:
    """Load repository-local delivery policy if present.

    Fails closed: if policy_path exists but cannot be parsed, raises ValueError.
    """
    if not os.path.exists(policy_path):
        return {}
    try:
        if yaml:
            with open(policy_path, "r", encoding="utf-8") as f:
                data = yaml.safe_load(f)
                if not isinstance(data, dict):
                    raise ValueError(f"Delivery policy {policy_path} must be a YAML mapping")
                return data
        with open(policy_path, "r", encoding="utf-8") as f:
            content = f.read()
        return _parse_yaml_fallback(content)
    except Exception as err:
        print(f"Error: could not parse delivery policy {policy_path}: {redact_secrets(str(err))}", file=sys.stderr)
        raise ValueError(f"Invalid delivery policy at {policy_path}: {err}") from err


def validate_delivery_gate(
    issue: dict,
    stage: str,
    expected_repo: str,
    jira_client: SimpleJiraClient | None = None,
    policy: dict | None = None,
) -> None:
    """Validate that the issue satisfies the delivery gate requirements for the stage."""
    fields = issue.get("fields") or {}
    labels = fields.get("labels") or []
    ticket_id = issue.get("key", "")

    # 1. Route validation & cardinality
    validate_route_cardinality(labels, expected_repo)

    # 2. Work-type awareness
    issuetype = fields.get("issuetype") or {}
    type_name = (issuetype.get("name") or "").lower()
    if type_name in ("sub-task", "subtask"):
        raise ValueError(f"Delivery gate rejected: Issue type '{type_name}' is not eligible for delivery.")

    # 3. Optional sprint policy: sprint presence or absence never fails the gate
    # (Sprint field is accepted if present, but never required)

    # 4. Stage-specific rules
    stages_cfg = policy.get("stages", {}) if isinstance(policy, dict) else {}
    if not isinstance(stages_cfg, dict):
        stages_cfg = {}
    stage_policy = stages_cfg.get(stage, {}) if isinstance(stages_cfg, dict) else {}
    if not isinstance(stage_policy, dict):
        stage_policy = {}
    if stage == "triage":
        req_label = stage_policy.get("required_request_label", "ready-for-triage")
        if req_label not in labels:
            raise ValueError(
                f"Delivery gate rejected: Missing authorized '{req_label}' label. "
                "Auto-backlog triage is excluded in v1."
            )
    elif stage == "code":
        req_label = stage_policy.get("required_request_label", "ready-to-code")
        requires_triage = stage_policy.get("requires_triage_pass", True)

        if requires_triage:
            has_triaged_label = "triaged" in labels
            has_triage_property = False
            if jira_client:
                try:
                    triage_prop = jira_client.get_issue_property(ticket_id, TRIAGE_PROPERTY_KEY)
                    if isinstance(triage_prop, dict):
                        status = (triage_prop.get("status") or "").lower()
                        if status in ("passed", "completed", "success", "approved", "pass", "ready"):
                            has_triage_property = True
                except Exception:
                    pass

            if not (has_triaged_label or has_triage_property):
                raise ValueError(
                    "Delivery gate rejected: Code stage requires passing triage first. "
                    "Missing 'triaged' label or triage assessment."
                )

        if req_label not in labels:
            raise ValueError(
                f"Delivery gate rejected: Missing authorized '{req_label}' label."
            )
    else:
        raise ValueError(f"Invalid delivery stage '{stage}'. Must be 'triage' or 'code'.")


def acquire_lease(
    jira: SimpleJiraClient,
    ticket_id: str,
    stage: str,
    holder: str,
    ttl_minutes: int = DEFAULT_LEASE_TTL_MINUTES,
    force: bool = False,
) -> dict:
    """Acquire authoritative claim lease via Jira entity property."""
    existing = jira.get_issue_property(ticket_id, CLAIM_PROPERTY_KEY)
    now = datetime.now(timezone.utc)

    if existing and isinstance(existing, dict) and not force:
        status = existing.get("status")
        expires_at_str = existing.get("expires_at")
        existing_holder = existing.get("holder")

        if status == "active" and expires_at_str:
            try:
                expires_at = datetime.fromisoformat(expires_at_str.replace("Z", "+00:00"))
                if expires_at > now and existing_holder != holder:
                    raise RuntimeError(
                        f"Claim contention: Ticket {ticket_id} is actively claimed by "
                        f"'{existing_holder}' until {expires_at_str}."
                    )
            except (ValueError, TypeError):
                pass

    lease_id = str(uuid.uuid4())
    acquired_at = now.isoformat()
    expires_at = datetime.fromtimestamp(now.timestamp() + (ttl_minutes * 60), tz=timezone.utc).isoformat()

    new_lease = {
        "lease_id": lease_id,
        "holder": holder,
        "stage": stage,
        "acquired_at": acquired_at,
        "expires_at": expires_at,
        "status": "active",
    }

    jira.set_issue_property(ticket_id, CLAIM_PROPERTY_KEY, new_lease)
    return new_lease


def reread_and_validate(jira: SimpleJiraClient, ticket_id: str, expected_lease: dict) -> None:
    """Re-read entity property to detect race conditions."""
    current = jira.get_issue_property(ticket_id, CLAIM_PROPERTY_KEY)
    if not current or not isinstance(current, dict):
        raise RuntimeError(f"Claim lost: Entity property {CLAIM_PROPERTY_KEY} missing after claim write.")

    if current.get("lease_id") != expected_lease.get("lease_id"):
        raise RuntimeError(
            f"Claim contention race lost: Expected lease {expected_lease.get('lease_id')}, "
            f"but found lease {current.get('lease_id')} held by '{current.get('holder')}'."
        )


def dispatch_local_workflow(ticket_id: str, stage: str, repo: str) -> None:
    """Dispatch the repository-local workflow using least-privilege Actions token."""
    workflow_file = f"fullsend-{stage}.yaml"
    cmd = [
        "gh",
        "workflow",
        "run",
        workflow_file,
        "--repo",
        repo,
        "--field",
        f"ticket={ticket_id}",
    ]
    print(f"Dispatching repository-local workflow {workflow_file} for ticket {ticket_id}...")
    proc = subprocess.run(cmd, text=True, capture_output=True)
    if proc.returncode != 0:
        clean_err = redact_secrets(proc.stderr)
        raise RuntimeError(f"Workflow dispatch failed: {clean_err}")


def release_lease(jira: SimpleJiraClient, ticket_id: str, lease: dict, status: str = "completed") -> None:
    """Release or mark lease complete."""
    lease["status"] = status
    lease["released_at"] = datetime.now(timezone.utc).isoformat()
    try:
        jira.set_issue_property(ticket_id, CLAIM_PROPERTY_KEY, lease)
    except Exception as err:
        print(f"Warning: could not update lease release state: {redact_secrets(str(err))}")


def reconcile_stage_completion(
    jira: SimpleJiraClient,
    ticket_id: str,
    stage: str,
    lease: dict,
    policy: dict | None = None,
    success: bool = True,
) -> None:
    """Reconcile Jira state upon workflow execution completion."""
    policy = policy or load_delivery_policy()
    stages_cfg = policy.get("stages", {}) if isinstance(policy, dict) else {}
    if not isinstance(stages_cfg, dict):
        stages_cfg = {}
    stage_cfg = stages_cfg.get(stage, {}) if isinstance(stages_cfg, dict) else {}
    if not isinstance(stage_cfg, dict):
        stage_cfg = {}

    req_label = stage_cfg.get(
        "required_request_label", "ready-for-triage" if stage == "triage" else "ready-to-code"
    )
    output_label = stage_cfg.get("output_label", "triaged" if stage == "triage" else "fullsend-code-completed")
    projections_cfg = policy.get("projections", {}) if isinstance(policy, dict) else {}
    if not isinstance(projections_cfg, dict):
        projections_cfg = {}
    in_progress_label = projections_cfg.get("in_progress_label", "fullsend-in-progress")

    jira.remove_label(ticket_id, in_progress_label)
    if success:
        jira.remove_label(ticket_id, req_label)
        if output_label:
            jira.add_label(ticket_id, output_label)
        release_lease(jira, ticket_id, lease, status="completed")
    else:
        release_lease(jira, ticket_id, lease, status="failed")


def run_delivery_cycle(
    ticket_id: str,
    stage: str,
    repo: str,
    jira_url: str,
    jira_email: str,
    jira_token: str,
    run_id: str = "0",
    force: bool = False,
    dry_run: bool = False,
) -> None:
    """Execute the full 6-stage delivery cycle."""
    holder = f"github:{repo}#{run_id}"
    print(f"=== UIE Fullsend Delivery Controller ===")
    print(f"Ticket: {ticket_id}")
    print(f"Stage: {stage}")
    print(f"Repository: {repo}")
    print(f"Holder: {holder}")

    policy = load_delivery_policy()
    lease_cfg = policy.get("lease", {}) if isinstance(policy, dict) else {}
    if not isinstance(lease_cfg, dict):
        lease_cfg = {}
    ttl_minutes = lease_cfg.get("ttl_minutes", DEFAULT_LEASE_TTL_MINUTES)
    projections_cfg = policy.get("projections", {}) if isinstance(policy, dict) else {}
    if not isinstance(projections_cfg, dict):
        projections_cfg = {}
    in_progress_label = projections_cfg.get("in_progress_label", "fullsend-in-progress")
    dispatched_prefix = projections_cfg.get("dispatched_label_prefix", "fullsend")
    dispatched_label = f"{dispatched_prefix}-{stage}-dispatched"

    jira = SimpleJiraClient(jira_url, jira_email, jira_token)

    # 1. Validate
    print("Stage 1: Validating delivery gate & route contract...")
    issue = jira.get_issue(ticket_id)
    validate_delivery_gate(issue, stage, repo, jira_client=jira, policy=policy)
    print("Delivery gate passed.")

    if dry_run:
        print("[DRY RUN] Validation succeeded; stopping before claim and mutations.")
        return

    # 2. Claim (Authoritative Entity Property Lease)
    print("Stage 2: Acquiring authoritative lease on Jira entity property...")
    lease = acquire_lease(jira, ticket_id, stage, holder, ttl_minutes=ttl_minutes, force=force)
    print(f"Claim lease written (lease_id={lease['lease_id']}).")

    # 3. Re-read / Revalidate
    print("Stage 3: Re-reading entity property to verify claim ownership...")
    reread_and_validate(jira, ticket_id, lease)
    print("Claim ownership verified without contention.")

    # Apply Projections (Labels & Comments)
    print("Applying initial projections...")
    jira.add_label(ticket_id, in_progress_label)
    jira.add_label(ticket_id, dispatched_label)
    # Durable attribution (FRFLY-800): apply fullsend-used immediately before validated agent run
    jira.add_label(ticket_id, "fullsend-used")
    jira.add_comment(
        ticket_id,
        f"🤖 **Fullsend Delivery Controller** has claimed this issue for **{stage}** delivery.\n\n"
        f"- **Repository:** `{repo}`\n"
        f"- **Claim Lease ID:** `{lease['lease_id']}`\n"
        f"- **Runner:** `{holder}`",
    )

    dispatch_error = None
    # 4. Dispatch
    try:
        print("Stage 4: Dispatching repository-local workflow...")
        dispatch_local_workflow(ticket_id, stage, repo)
        print("Local workflow dispatched successfully.")
    except Exception as exc:
        dispatch_error = exc
        print(f"Dispatch error: {redact_secrets(str(exc))}")

    # 5. Evidence
    print("Stage 5: Recording delivery evidence...")
    evidence = {
        "ticket": ticket_id,
        "stage": stage,
        "repository": repo,
        "lease_id": lease["lease_id"],
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "status": "failed" if dispatch_error else "dispatched",
        "error": redact_secrets(str(dispatch_error)) if dispatch_error else None,
    }
    print(f"Evidence: {json.dumps(evidence)}")

    # 6. Reconcile
    if dispatch_error:
        print("Stage 6: Dispatch failed; rolling back projections and marking lease failed...")
        jira.remove_label(ticket_id, in_progress_label)
        jira.remove_label(ticket_id, dispatched_label)
        release_lease(jira, ticket_id, lease, status="failed")
        jira.add_comment(
            ticket_id,
            f"❌ **Fullsend Delivery Controller** encountered an error during **{stage}** dispatch:\n\n"
            f"```\n{redact_secrets(str(dispatch_error))}\n```\n"
            f"Lease has been released.",
        )
        raise dispatch_error

    print("Stage 6: Workflow dispatched asynchronously; claim lease remains active during agent execution.")
    jira.add_comment(
        ticket_id,
        f"🚀 **Fullsend Delivery Controller** dispatched **{stage}** workflow successfully.\n\n"
        f"- **Repository:** `{repo}`\n"
        f"- **Claim Lease ID:** `{lease['lease_id']}`\n"
        f"- **Status:** Workflow queued/running; claim lease remains active during execution.",
    )
    print("Dispatch reconciliation complete.")


def main() -> int:
    parser = argparse.ArgumentParser(description="Fullsend Jira Delivery Controller")
    parser.add_argument("--ticket", required=False, help="Jira ticket key (e.g. FRFLY-123)")
    parser.add_argument("--stage", default="triage", choices=["triage", "code"], help="Delivery stage")
    parser.add_argument("--repo", default=os.environ.get("GITHUB_REPOSITORY"), help="GitHub repository (owner/repo)")
    parser.add_argument("--force", action="store_true", help="Force claim override")
    parser.add_argument("--dry-run", action="store_true", help="Dry run validation without mutations")
    parser.add_argument("--poll", action="store_true", help="Poll for tickets")
    parser.add_argument("--reconcile", "--complete", action="store_true", help="Reconcile stage completion")
    parser.add_argument("--status", choices=["success", "failed"], default="success", help="Completion status (default: success)")

    args = parser.parse_args()

    repo = args.repo or os.environ.get("GITHUB_REPOSITORY")
    if not repo:
        print("Error: GITHUB_REPOSITORY environment variable or --repo option required.", file=sys.stderr)
        return 1

    jira_url = os.environ.get("FULLSEND_JIRA_URL", DEFAULT_JIRA_URL)
    jira_email = os.environ.get("FULLSEND_JIRA_EMAIL", os.environ.get("JIRA_EMAIL", ""))
    jira_token = os.environ.get("FULLSEND_JIRA_API_TOKEN", os.environ.get("JIRA_API_TOKEN", ""))

    if not jira_token:
        print("Error: FULLSEND_JIRA_API_TOKEN or JIRA_API_TOKEN is required.", file=sys.stderr)
        return 1

    if args.reconcile:
        if not args.ticket:
            print("Error: --ticket is required for reconciliation.", file=sys.stderr)
            return 1
        jira = SimpleJiraClient(jira_url, jira_email, jira_token)
        lease = jira.get_issue_property(args.ticket, CLAIM_PROPERTY_KEY) or {}
        is_success = args.status == "success"
        try:
            reconcile_stage_completion(
                jira=jira,
                ticket_id=args.ticket,
                stage=args.stage,
                lease=lease,
                success=is_success,
            )
            print(f"Reconciled stage '{args.stage}' completion for ticket {args.ticket} (status={args.status}).")
            return 0
        except Exception as exc:
            print(f"Reconciliation Error: {redact_secrets(str(exc))}", file=sys.stderr)
            return 1

    if args.poll:
        print("Polling mode is active; checking for tickets...")
        # Polling can be extended; in v1, requires explicit ticket
        return 0

    if not args.ticket:
        print("Error: --ticket is required.", file=sys.stderr)
        return 1

    run_id = os.environ.get("GITHUB_RUN_ID", "local")

    try:
        run_delivery_cycle(
            ticket_id=args.ticket,
            stage=args.stage,
            repo=repo,
            jira_url=jira_url,
            jira_email=jira_email,
            jira_token=jira_token,
            run_id=run_id,
            force=args.force,
            dry_run=args.dry_run,
        )
        return 0
    except Exception as exc:
        print(f"Delivery Controller Error: {redact_secrets(str(exc))}", file=sys.stderr)
        return 1


if __name__ == "__main__":
    sys.exit(main())
